known且所有命令0调用，真实empty→合法入口；已有draft/编辑后重新读取失败→cache明确历史/不再verified current/所有写按钮及restore禁用/输入保留/Receipt不消失；重新读取成功→当前状态恢复只读显示和既有guard，失败期间没有execute重发；成功命令history失败原回归、stale async load不覆盖新snapshot。先独立plan合法消费、最小2文件修改，Vitest本组件/API strictclient及相邻工作台、typecheck按已装环境（不改pnpm锁或重装）。真实浏览器所有动作限read/UI，不保存/approve/execute；故障UI验收使用授权隔离localfixture/受控client响应，不在原库造坏数据。按原稿三视口只核状态显示/不遮挡和主结构；1280按钮裁切与价格255px仍另待，不能P1合格。\\n\\nUI与root接线需各自代码质量/精确最新已提交冻结/API和Web fresh维护门/原真人GET菜单/650指纹/独立现场Prime及准确各scopeDelivery之后才同步Authority/Prime。日报及每次aos仍最新m1原权威卷完整PG→API→Web；aos-2不重启。完整BudgetC/用户最后真实批准/原部署/自然首链/安装全生命周期/八场景/全视觉/观察发布仍未完成。\\n\\nFILE .evidence/qyh-creator-workflow-read-failure-ui-20261014/proposed-diff-r1.txt SHA 333a2ec514e782670f52c64d01b7c0022105e31932ea484693fd4200c258d227\\n--- /Users/ddt/work/projects/ai_agent/aos-platform/apps/web/src/components/workshop/CreatorGrowthPage.tsx CURRENT\\n+++ /Users/ddt/work/projects/ai_agent/aos-platform/apps/web/src/components/workshop/CreatorGrowthPage.tsx PROSPECTIVE NOT APPLIED\\n@@ -112,7 +112,7 @@\\n const WORKFLOW_STATUS: Record<CreatorInternalWorkflowDraft[\\\"status\\\"], string> = { draft: \\\"草稿\\\", in_review: \\\"审核中\\\", approved: \\\"已批准\\\", rejected: \\\"已驳回\\\" };\\n const detailText = (details: Record<string, unknown> | undefined, key: string) => typeof details?.[key] === \\\"string\\\" ? String(details[key]) : \\\"\\\";\\n \\n-function PreparationPanel({ purpose, products, current, receipt, history, busy, error, onClose, onCommand, onNew }: { purpose: CreatorInternalWorkflowPurpose; products: ContentCampaignProductInput[]; current: CreatorInternalWorkflowDraft | null; receipt: CreatorInternalWorkflowReceipt | null; history: CreatorInternalWorkflowDraft[]; busy: boolean; error: string; onClose: () => void; onCommand: (command: CreatorInternalWorkflowCommand, values: { title: string; summary: string; details: Record<string, unknown> }, restoreRevision?: number) => void; onNew: () => void }) {\\n+function PreparationPanel({ purpose,